node -e "
const ajv8 = require('./node_modules/ajv');
const ajv6 = require('./node_modules/eslint/node_modules/ajv');
const A8 = ajv8.default ?? ajv8;
const A6 = ajv6.default ?? ajv6;

const opts = {strict: false, validateFormats: false, format: false, jsonPointers: true, logger: false, allErrors: true};
const c8 = new A8(opts);
const c6 = new A6(opts);

// 1. invalid schema throws?
for (const [label, c] of [['v8', c8], ['v6', c6]]) {
  try {
    c.compile({type: 'not-a-json-schema-type'});
    console.log(label, 'DID NOT THROW on invalid schema');
  } catch (e) {
    console.log(label, 'threw on invalid schema:', e.message);
  }
}

// 2. unknown keyword + custom format + date-time format
const openApiSchema = {
  type: 'object',
  properties: {
    startsAt: {type: 'string', format: 'date-time', example: '2026-01-01'},
    custom: {type: 'string', format: 'my-custom-format', 'x-vendor': 123},
  },
  required: ['startsAt'],
};
console.log('v8 openApi valid:', c8.compile(openApiSchema)({startsAt: 'not-a-date', custom: 'anything', extra: 1}));
console.log('v6 openApi valid:', c6.compile(openApiSchema)({startsAt: 'not-a-date', custom: 'anything', extra: 1}));

// 3. nested required, nested type, enum, array item
const complexSchema = {
  type: 'object',
  properties: {
    cabin: {type: 'string', enum: ['economy', 'business']},
    passenger: {
      type: 'object',
      properties: {passportNumber: {type: 'string'}},
      required: ['passportNumber'],
    },
    legs: {
      type: 'array',
      items: {type: 'object', properties: {seat: {type: 'number'}}, required: ['seat']},
    },
  },
  required: ['cabin', 'passenger'],
};
const v8 = c8.compile(complexSchema);
const v6 = c6.compile(complexSchema);

v8({cabin: 'vip', passenger: {}, legs: [{seat: 'bad'}]});
v6({cabin: 'vip', passenger: {}, legs: [{seat: 'bad'}]});
console.log('v8 complex errors:', v8.errors);
console.log('v6 complex errors:', v6.errors);
"

